import json
schema=json.load(open('[REDACTED LOCAL PATH]'))

def walk(x,path=''):
    if isinstance(x,dict):
        name=x.get('name')
        typ=x.get('type')
        label=x.get('label')
        if name or typ:
            print(path, 'name=',name,'type=',typ,'label=',label,'value=',x.get('value'))
        for k in ('inputs','cases','parameters'):
            if k in x:
                walk(x[k], path+'/'+str(name or x.get('value') or k))
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v,path+f'[{i}]')
walk(schema.get('inputs',[]))
